import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Blacksmithing","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/blacksmithing.md","filePath":"en/guide/professions/blacksmithing.md"}'),n={name:"en/guide/professions/blacksmithing.md"};function s(d,e,o,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="blacksmithing" tabindex="-1">Blacksmithing <a class="header-anchor" href="#blacksmithing" aria-label="Permalink to &quot;Blacksmithing&quot;">​</a></h1><p><strong>Status:</strong> Proposed · New design not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Blacksmithing combines metallurgy, equipment production and maintenance.</li><li>Materials and workmanship create trade-offs; better skill does not make Masterworks routine.</li><li>Field assessment and repair are proposed utilities beyond workshop production.</li></ul><p>Blacksmithing turns metal into dependable equipment. Materials and process should produce meaningful trade-offs instead of a single quality ladder.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Proposed role</th></tr></thead><tbody><tr><td>Processes</td><td>Smelt, refine, alloy, forge, heat-treat, finish</td></tr><tr><td>Field work</td><td>Assess, sharpen, perform minor repairs and maintenance</td></tr><tr><td>Journal</td><td>Learn materials and metallurgical processes</td></tr><tr><td>Techniques</td><td>Bladesmithing and Armorsmithing</td></tr></tbody></table><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Choice</th><th>Consideration</th></tr></thead><tbody><tr><td>Hard edge</td><td>Can be brittle</td></tr><tr><td>Tough construction</td><td>Weight and durability compete</td></tr><tr><td>Better skill</td><td>Broadens capable work; does not make Masterworks routine</td></tr><tr><td>Arms Lore</td><td>Martial performance knowledge</td></tr><tr><td>Blacksmithing</td><td>Material and structural understanding</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A smith may become known for durable field weapons or lightweight armor through workmanship. Exact repair and material rules remain open.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry composites</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Shared learning and batches</a> · <a href="/Syrolands-Public/en/game-design/professions/blacksmithing.html">Full specification</a></p><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span></p>',14)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
